To reproduce in an isolated exact-head checkout with normal frozen dependencies, save the following uncommitted driver at `src/gateway/final-effect.proof.test.ts`. The receiving clients connect only to a synthetic loopback server; no external service or model is used.

```typescript
import assert from "node:assert/strict";
import { once } from "node:events";
import type { IncomingMessage } from "node:http";
import { appendFileSync } from "node:fs";
import { it } from "vitest";
import { WebSocket, WebSocketServer } from "ws";
import { setRuntimeConfigSnapshot } from "../config/runtime-snapshot.js";
import { upsertSessionEntryCore } from "../config/sessions/session-accessor.js";
import { ensureProfileForEmail } from "../state/user-profiles.js";
import { withOpenClawTestState } from "../test-utils/openclaw-test-state.js";
import { createTestGatewayScheduler } from "../test-utils/gateway-scheduler-clock.js";
import { prepareGatewayRecipientProfile } from "./expected-profile.js";
import { createGatewayConnectionState } from "./server-connection-state.js";
import { createGatewayRequestContext } from "./server-request-context.js";
import { makeContextParams } from "./server-request-context.test-support.js";
import { callSessionSharingHandler } from "./server-methods/sessions-sharing.test-support.js";
import { gatewayConnect, gatewayProfile } from "./server/client-fixtures.test-support.js";
import { createSessionRowProjection } from "./session-row-projection.js";
import { createGatewayWebSocketTransport } from "./server/ws-transport.js";
import { installGatewayDeflateCodec } from "./server/ws-compression.js";
import type { GatewayWsClient } from "./server/ws-types.js";

const receiptPath = process.env.AUTHORITY_PROOF_RECEIPT!;
let sequence = 0;
function record(kind: string, facts: Record<string, unknown> = {}) {
  const row = { sequence: ++sequence, kind, ...facts };
  appendFileSync(receiptPath, JSON.stringify(row) + "\n");
  console.log("AUTHORITY_PROOF", JSON.stringify(row));
}
function identify(client: GatewayWsClient, profileId: string) {
  client.authenticatedUserProfile = { ...gatewayProfile(profileId), avatarRevision: "proof" };
  prepareGatewayRecipientProfile(client);
}
async function transport(server: WebSocketServer, name: string, profileId: string) {
  const address = server.address();
  assert(address && typeof address !== "string");
  const accepted = once(server, "connection");
  const wire = new WebSocket(`ws://127.0.0.1:${address.port}`);
  const received: Array<{ event?: string; payload?: unknown; proofBarrier?: number }> = [];
  wire.on("message", (data) => {
    const frame = JSON.parse(data.toString());
    received.push(frame);
    if (frame.event === "session.access.changed") record("wire-received", { recipient: name, payload: frame.payload });
  });
  await once(wire, "open");
  const [socket, request] = await accepted as [WebSocket, IncomingMessage];
  const sends: unknown[] = [];
  const nativeSends: unknown[] = [];
  const originalNativeSend = socket.send;
  socket.send = function (...args: Parameters<typeof socket.send>) {
    const frame = JSON.parse(String(args[0]));
    if (frame.event === "session.access.changed") {
      nativeSends.push(frame.payload);
      record("native-websocket-send", { recipient: name, payload: frame.payload });
    }
    return Reflect.apply(originalNativeSend, this, args);
  } as typeof socket.send;
  const stream = request.socket;
  // Same adapter and codec owner used by server/ws-connection.ts.
  const gatewayTransport = createGatewayWebSocketTransport(socket, stream, installGatewayDeflateCodec(socket));
  const originalSend = gatewayTransport.send;
  gatewayTransport.send = function (...args: Parameters<typeof gatewayTransport.send>) {
    const frame = JSON.parse(String(args[0]));
    const isAccess = frame.event === "session.access.changed";
    if (isAccess) {
      sends.push(frame.payload);
      record("transport-send", { recipient: name, payload: frame.payload });
    }
    return Reflect.apply(originalSend, this, args);
  } as typeof gatewayTransport.send;
  socket.on("error", (error) => record("server-socket-error", { recipient: name, message: error.message }));
  wire.on("error", (error) => record("client-socket-error", { recipient: name, message: error.message }));
  const client: GatewayWsClient = {
    socket: gatewayTransport, connId: name, usesSharedGatewayAuth: false,
    connect: gatewayConnect(["operator.read", "operator.write"], { platform: "web" }),
  };
  identify(client, profileId);
  let barrier = 0;
  return {
    client, wire, socket, sends, nativeSends, received,
    clear() { sends.length = 0; nativeSends.length = 0; received.length = 0; },
    async drain() {
      assert.equal(socket.readyState, WebSocket.OPEN, "server transport closed before barrier");
      assert.equal(wire.readyState, WebSocket.OPEN, "client transport closed before barrier");
      const marker = ++barrier;
      await new Promise<void>((resolve, reject) => {
        const cleanup = () => {
          clearTimeout(deadline);
          wire.off("message", listener);
          wire.off("close", closed);
          wire.off("error", failed);
        };
        const failed = (error: Error) => { cleanup(); reject(error); };
        const closed = () => failed(new Error("transport closed before ordered barrier"));
        const listener = (data: Buffer) => {
          if (JSON.parse(data.toString()).proofBarrier === marker) { cleanup(); resolve(); }
        };
        const deadline = setTimeout(() => failed(new Error("ordered wire barrier deadline")), 5000);
        wire.on("message", listener);
        wire.once("close", closed);
        wire.once("error", failed);
        socket.send(JSON.stringify({ proofBarrier: marker }), (error) => { if (error) failed(error); });
      });
      assert.equal(socket.readyState, WebSocket.OPEN);
      assert.equal(wire.readyState, WebSocket.OPEN);
    },
    async close() {
      const closed = wire.readyState === WebSocket.CLOSED ? Promise.resolve() : once(wire, "close");
      const serverClosed = socket.readyState === WebSocket.CLOSED ? Promise.resolve() : once(socket, "close");
      if (wire.readyState !== WebSocket.CLOSED) wire.close(1000, "proof complete");
      await Promise.all([closed, serverClosed]);
    },
  };
}

for (const drift of ["identity", "write-scope", "read-scope"] as const) {
  it(`real WebSocket rejects captured access publication after ${drift} drift`, async () => {
    await withOpenClawTestState({ scenario: "minimal", prepareProfileCatalog: true }, async () => {
      const cfg = {};
      setRuntimeConfigSnapshot(cfg);
      const owner = ensureProfileForEmail(`owner-${drift}@example.test`);
      const viewer = ensureProfileForEmail(`viewer-${drift}@example.test`);
      const unaffected = ensureProfileForEmail(`control-${drift}@example.test`);
      const replacement = ensureProfileForEmail(`replacement-${drift}@example.test`);
      const scope = { agentId: "main", sessionKey: `agent:main:final-effect-${drift}` };
      const sessionId = `final-effect-${drift}`;
      await upsertSessionEntryCore(scope, {
        sessionId, updatedAt: 1, visibility: "shared",
        createdActor: { type: "human", source: "profile", id: owner.id },
      });
      const state = createGatewayConnectionState({ scheduler: createTestGatewayScheduler(), bootId: `final-effect-${drift}`, cfg });
      const projection = await createSessionRowProjection({ cfg, modelCatalog: [] });
      const detach = state.attachSessionRowProjection(projection);
      const server = new WebSocketServer({ host: "127.0.0.1", port: 0 });
      await once(server, "listening");
      const peers: Awaited<ReturnType<typeof transport>>[] = [];
      try {
        await projection.ensureMaterialized();
        for (const [name, profile] of [["owner", owner], ["viewer", viewer], ["unaffected", unaffected]] as const) {
          const peer = await transport(server, `${drift}-${name}`, profile.id);
          peers.push(peer);
          state.clients.add(peer.client);
        }
        const [ownerPeer, viewerPeer, controlPeer] = peers;
        const context = createGatewayRequestContext(makeContextParams(state));
        const change = async (visibility: string) => {
          const result = await callSessionSharingHandler("session.visibility.set", { ...scope, visibility }, context, ownerPeer.client);
          assert.equal(result[0]?.[0], true, JSON.stringify(result));
          assert.equal(projection.sharingTarget({ agentId: "main", key: scope.sessionKey })?.entry.visibility, visibility);
          await Promise.all(peers.map((peer) => peer.drain()));
          return result;
        };
        record("case-start", { drift, head: "40267a5b05246c960ea6f059346871304a15fb52", sessionId });
        // Positive delivery through the same physical transport before the interleave.
        await change("read-only");
        assert.equal(viewerPeer.sends.length, 1);
        assert.equal(controlPeer.sends.length, 1);
        assert.equal(viewerPeer.received.filter((f) => f.event === "session.access.changed").length, 1);
        await change("shared");
        peers.forEach((p) => p.clear());
        const nativePrepare = state.prepareSessionAccessChange;
        let prepared = 0;
        let published = 0;
        context.prepareSessionAccessChange = (target) => {
          const publish = nativePrepare(target);
          prepared++;
          record("native-preparation-returned", { drift, visibility: target.entry.visibility, sessionId: target.entry.sessionId });
          return () => {
            const committed = projection.sharingTarget({ agentId: "main", key: scope.sessionKey });
            assert.equal(committed?.entry.visibility, "read-only");
            assert.equal(committed?.entry.sessionId, sessionId);
            record("sharing-commit-observed", { drift, visibility: "read-only", sessionId });
            if (drift === "identity") {
              identify(viewerPeer.client, replacement.id);
              assert.equal(viewerPeer.client.preparedRecipientProfileId, replacement.id);
              record("recipient-identity-reassigned", { drift, canonicalPreparation: "prepareGatewayRecipientProfile", identities: "distinct synthetic resident profiles" });
            } else {
              viewerPeer.client.connect.scopes = drift === "write-scope" ? ["operator.read"] : [];
              record("recipient-scope-revoked", { drift, before: ["operator.read", "operator.write"], after: viewerPeer.client.connect.scopes });
            }
            published++;
            record("native-publication-invoked", { drift });
            publish();
            record("native-publication-returned", { drift, targetAccessSendCount: viewerPeer.sends.length, unaffectedAccessSendCount: controlPeer.sends.length });
          };
        };
        await change("read-only");
        assert.equal(prepared, 1);
        assert.equal(published, 1);
        assert.equal(viewerPeer.sends.length, 0);
        assert.equal(viewerPeer.received.filter((f) => f.event === "session.access.changed").length, 0);
        assert.deepEqual(controlPeer.sends, [{ ...scope, sessionId, access: "read-only" }]);
        assert.equal(controlPeer.received.filter((f) => f.event === "session.access.changed").length, 1);
        record("negative-verdict", { drift, targetSendCount: 0, targetWireFrameCount: 0, unaffectedSendCount: 1, unaffectedWireFrameCount: 1, targetTransportStillOpen: true, orderedWireBarrierReceived: true });
        // Restore the same target connection and prove subsequent native publication still delivers.
        context.prepareSessionAccessChange = nativePrepare;
        identify(viewerPeer.client, viewer.id);
        viewerPeer.client.connect.scopes = ["operator.read", "operator.write"];
        peers.forEach((p) => p.clear());
        await change("shared");
        assert.deepEqual(viewerPeer.sends, [{ ...scope, sessionId, access: "read-write" }]);
        assert.equal(viewerPeer.received.filter((f) => f.event === "session.access.changed").length, 1);
        record("restored-positive-delivery", { drift, sameTransport: true, targetSendCount: 1, targetWireFrameCount: 1 });
      } finally {
        for (const peer of peers) state.clients.delete(peer.client);
        await Promise.all(peers.map((p) => p.close()));
        await new Promise<void>((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
        detach(); projection.dispose(); await state.mentionInbox.dispose();
        record("transport-cleanup-complete", { drift, socketsClosed: peers.length * 2, listenerClosed: true });
      }
    });
    record("state-cleanup-complete", { drift });
  }, 120_000);
}
